const data = $('Webhook generar-anexos').item.json.body;
const plantillas = data.plantillasBase64 || [];
const empresa = data.empresa || {};
const pliego = data.pliego || {};

// Extraer contexto procesado de la empresa
const contexto = typeof empresa.contexto_procesado === 'string'
  ? JSON.parse(empresa.contexto_procesado)
  : (empresa.contexto_procesado || {});

// Extraer analisis del pliego
const analisis = typeof pliego.analisis === 'string'
  ? JSON.parse(pliego.analisis)
  : (pliego.analisis || {});

return [{
  json: {
    anexoId: data.anexoId,
    pliegoId: data.pliegoId,
    empresaId: data.empresaId,
    abogadoId: data.abogadoId,
    plantillas,
    empresaData: {
      nombre: empresa.nombre || '',
      nit: empresa.nit || '',
      sector: empresa.sector || '',
      contexto,
    },
    pliegoData: {
      nombre: pliego.nombre || '',
      secop_id: pliego.secop_id || '',
      analisis,
    }
  }
}];

const data = $('Code - Preparar datos').item.json;
const plantillas = data.plantillas;

const systemPrompt = 'Eres un asistente juridico experto en contratacion publica colombiana (SECOP II). ' +
'Tu tarea es llenar campos de plantillas de licitacion con datos reales de la empresa. ' +
'CRITICO: El campo_original en tu respuesta debe ser el texto EXACTO entre corchetes ' +
'tal como aparece en el documento, incluyendo los corchetes. ' +
'NO resumir, NO cambiar el texto del campo. Copiarlo exactamente como esta. ' +
'Si no tienes el dato para ese campo, usar encontrado: false y dejar valor_nuevo vacio. ' +
'campos_pendientes debe decir: "El abogado debe completar: [descripcion breve del dato]". ' +
'Devuelve UNICAMENTE JSON valido: ' +
'{"plantillas":[{"nombre":"string","reemplazos":[{"campo_original":"texto exacto con corchetes","valor_nuevo":"string","encontrado":true}],"campos_pendientes":["El abogado debe completar: ..."]}]}';

const empresaInfo = 'DATOS DE LA EMPRESA:\n' +
'Nombre/Razon social: ' + data.empresaData.nombre + '\n' +
'NIT: ' + data.empresaData.nit + '\n' +
'Sector: ' + data.empresaData.sector + '\n' +
'Perfil: ' + JSON.stringify(data.empresaData.contexto) + '\n\n';

const pliegoInfo = 'DATOS DEL PROCESO:\n' +
'Entidad: ' + (data.pliegoData.analisis?.entidad || data.pliegoData.nombre) + '\n' +
'Numero proceso: ' + (data.pliegoData.secop_id || 'Por confirmar') + '\n' +
'Objeto: ' + (data.pliegoData.analisis?.objeto || data.pliegoData.nombre) + '\n' +
'Municipio: ' + (data.pliegoData.analisis?.municipio || 'Roldanillo') + '\n' +
'Departamento: Valle del Cauca\n' +
'Ciudad y Departamento: ' + (data.pliegoData.analisis?.municipio || 'Roldanillo') + ', Valle del Cauca\n\n';

const descripcionPlantillas = data.plantillas.map(p => {
  const nombreLimpio = p.nombre.replace(/^\d+_/, '');
  return 'PLANTILLA: ' + nombreLimpio;
}).join('\n');

const camposTipicos =
  '- [NOMBRE DE LA ENTIDAD CONTRATANTE]\n' +
  '- [Número del Proceso de Contratación]\n' +
  '- [Número del proceso]\n' +
  '- [Objeto del contrato]\n' +
  '- [OBJETO DEL PROCESO]\n' +
  '- [Nombre del representante legal del proponente]\n' +
  '- [Nombre del proponente]\n' +
  '- [NIT]\n' +
  '- [NIT del proponente]\n' +
  '- [NIT Proponente]\n' +
  '- [Ciudad]\n' +
  '- [CIUDAD]\n' +
  '- [Ciudad, Departamento]\n' +
  '- [Dirección de la entidad]\n' +
  '- [Cédula del representante legal]\n' +
  '- [día] / [mes] / [año]\n' +
  '- [Nombre o razón social del proponente]';

const contratosTexto = data.empresaData.contexto?.contratos_ejecutados
  ? data.empresaData.contexto.contratos_ejecutados.map((c, i) => {
      const num = i + 1;
      return [
        '[Objeto del contrato similar] fila ' + num + ' -> ' + c.descripcion,
        '[Entidad] fila ' + num + ' -> ' + c.entidad,
        '[Valor $] fila ' + num + ' -> ' + c.valor_aproximado,
        '[dd/mm/aaaa] fecha inicio fila ' + num + ' -> ' + (c.ano.split('-')[0] || c.ano),
        '[dd/mm/aaaa] fecha fin fila ' + num + ' -> ' + (c.ano.split('-')[1] || 'Vigente'),
        '[Ejecutado / En ejecución] fila ' + num + ' -> ' + (c.ano.includes('vigente') ? 'En ejecución' : 'Ejecutado'),
        '[No. contrato] fila ' + num + ' -> El abogado debe completar: número oficial del contrato con ' + c.entidad,
      ].join('\n');
    }).join('\n\n')
  : '';

const userMessage = empresaInfo + pliegoInfo +
  'PLANTILLAS A LLENAR:\n' + descripcionPlantillas + '\n\n' +
  'Para cada plantilla identifica los campos entre corchetes y llénalos.\n\n' +
  'Campos tipicos SECOP II:\n' + camposTipicos + '\n\n' +
  (contratosTexto ?
    'DATOS REALES DE CONTRATOS EJECUTADOS (para tablas de experiencia):\n' +
    'La empresa tiene ' + (data.empresaData.contexto?.contratos_ejecutados?.length || 0) + ' contratos ejecutados.\n' +
    'Para el Formato de Experiencia, llenar cada fila con estos datos exactos:\n\n' +
    contratosTexto + '\n\n' +
    'IMPORTANTE: En tablas de experiencia, el campo [Objeto del contrato similar] de la columna header NO se reemplaza.\n' +
    'Solo reemplazar los campos en las filas de datos (filas 1, 2, 3...).\n' +
    'Usar campo_original con el texto EXACTO del campo en esa fila especifica.\n'
    : '') +
  'Si no tienes el dato usar encontrado: false.';

const content = [];

content.push({
  type: 'text',
  text: userMessage
});

for (const plantilla of plantillas) {
  if (plantilla.mediaType === 'application/pdf') {
    content.push({
      type: 'document',
      source: {
        type: 'base64',
        media_type: 'application/pdf',
        data: plantilla.base64
      },
      title: plantilla.nombre
    });
  } else {
    content.push({
      type: 'text',
      text: 'PLANTILLA: ' + plantilla.nombre + '\n[Archivo Word/Excel]'
    });
  }
}

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8192,
  system: systemPrompt,
  messages: [{ role: 'user', content }]
};

return [{
  json: {
    ...data,
    claudeBody: JSON.stringify(requestBody)
  }
}];

const response = $('Claude API - Generar anexos').item.json;
const buildData = $('Code - Build Claude Request').item.json;

let plantillas = [];
if (response.content && response.content[0] && response.content[0].text) {
  let texto = response.content[0].text.trim()
    .replace(/```json/g, '').replace(/```/g, '').trim();
  try {
    const parsed = JSON.parse(texto);
    plantillas = parsed.plantillas || [];
  } catch(e) {
    plantillas = [];
  }
}

// Combinar reemplazos con base64 original de cada plantilla
const plantillasConReemplazos = plantillas.map((p, i) => {
  const original = buildData.plantillas[i] || {};
  return {
    nombre: p.nombre || original.nombre,
    ruta_original: original.rutaEnDisco || '',
    base64_original: original.base64 || '',
    media_type: original.mediaType || '',
    reemplazos: p.reemplazos || [],
    campos_pendientes: p.campos_pendientes || []
  };
});

return [{
  json: {
    pliegoId: buildData.pliegoId,
    empresaId: buildData.empresaId,
    anexos: JSON.stringify(plantillasConReemplazos)
  }
}];
